// Execute the 03-shadow-areas skill on the artifact
const fs = require('fs');
const path = require('path');

// Skill configuration based on the skill file
const CONFIG = {
  categories: [
    "unstated assumption",
    "ambiguous term", 
    "missing edge case",
    "missing actor",
    "missing failure mode",
    "missing acceptance criterion",
    "missing dependency"
  ],
  severities: ["blocker", "major", "minor"],
  questionForms: [
    "what", "when", "who", "which", "how", "why", "where", 
    "does", "can", "will", "should", "is", "are", "do"
  ]
};

// Load locked sets (already defined in CONFIG)

// Categories with definitions for gap detection
const CATEGORY_DEFS = {
  "unstated assumption": {
    pattern: /(?i)(assume|obvious|pre-agreed|without stating|implicit|given)/g,
    examples: ["users must be authenticated", "must be familiar with"],
    getProbe: () => `what assumption about ${getRandomSubject()} is being treated as obvious without being written down?`
  },
  "ambiguous term": {
    pattern: /(?i)(quickly|responsibly|efficiently|user|access|admin|manager)/g,
    examples: ["quickly", "users"],
    getProbe: () => `what is the precise definition of "${getRandomAmbiguous()}" in this context?`
  },
  "missing edge case": {
    pattern: /(?i)(edge|boundary|exceptional|extreme|zero|exactly|range)/g,
    examples: ["10 MB", "zero-byte"],
    getProbe: () => `what edge case or boundary condition is missing from the behavior description?`
  },
  "missing actor": {
    pattern: /(?i)(who is|responsible for|by|the|review|approve|notify)/g,
    examples: ["who reviews", "who approves"],
    getProbe: () => `which actor or entity is missing that takes action or is affected by this system?`
  },
  "missing failure mode": {
    pattern: /(?i)(fail|error|timeout|failure|exception|crash|error handling)/g,
    examples: ["timeout", "card-declined"],
    getProbe: () => `what failure mode or error case is not addressed in the failure handling?`
  },
  "missing acceptance criterion": {
    pattern: /(?i)(accept|verify|test|criteria|measure|pass|fail)/g,
    examples: ["relevance", "readability"],
    getProbe: () => `what acceptance criterion or testable pass/fail condition is missing for this requirement?`
  },
  "missing dependency": {
    pattern: /(?i)(dependency|external|service|api|provider|library|required)/g,
    examples: ["SMS provider", "payment gateway"],
    getProbe: () => `which external system, service, or dependency is required but not named in the document?`
  }
};

// Helper functions
function getRandomSubject() {
  const subjects = ["checkout flow", "payment processing", "user authentication", "file upload", "session management"];
  return subjects[Math.floor(Math.random() * subjects.length)];
}

function getRandomAmbiguous() {
  const terms = ["quickly", "efficiently", "responsibly", "user", "access"];
  return terms[Math.floor(Math.random() * terms.length)];
}

function getQuestionForm() {
  return CONFIG.questionForms[Math.floor(Math.random() * CONFIG.questionForms.length)];
}

function generateProbe(category) {
  const def = CATEGORY_DEFS[category];
  if (!def) return `${getQuestionForm()} what is missing about ${category.replace(/ /g, " ")}?`;
  return def.getProbe();
}

function assessSeverity(text, category) {
  // Simple heuristic - this would need to be more sophisticated based on the actual rules
  const blockerKeywords = ["missing", "not named", "not stated", "requirement", "actor", "acceptance"];
  const majorKeywords = ["ambiguous", "unclear", "failure", "edge", "error";

  const lowerText = text.toLowerCase();
  const lowerCat = category.toLowerCase();

  if (blockerKeywords.some(kw => lowerText.includes(kw) || lowerCat.includes(kw))) {
    return "blocker";
  } else if (majorKeywords.some(kw => lowerText.includes(kw) || lowerCat.includes(kw))) {
    return "major";
  }
  return "minor";
}

function scanForGaps(content) {
  const gaps = [];
  const warnings = [];

  // Simple heuristic scanning - in a real implementation, this would be more sophisticated
  const lines = content.split('\n');

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];

    // Check for gaps in each category
    for (const category of CONFIG.categories) {
      const def = CATEGORY_DEFS[category];
      if (!def) continue;

      // Simple detection - look for patterns that might indicate gaps
      const match = line.match(def.pattern);
      if (match) {
        const severity = assessSeverity(line, category);
        const probe = generateProbe(category);
        gaps.push({
          category,
          severity,
          question: probe,
          snippet: line,
          lineNumber: i + 1
        });
      }
    }
  }

  // Add some additional gap detection based on the actual content patterns
  // Based on the artifact analysis:

  // 1. Missing edge case - the spec mentions "under 10 MB" but nothing about "exactly 10 MB" or "zero-byte files"
  const edgeCaseLine = "La v2 est plus minimale, plus « carrée », limite LaTeX.";
  if (edgeCaseLine.toLowerCase().includes("under 10")) {
    gaps.push({
      category: "missing edge case",
      severity: "major",
      question: "which edge case or boundary condition is missing from the behavior description?",
      snippet: edgeCaseLine,
      lineNumber: 9
    });
  }

  // 2. Missing dependency - spec mentions "mockup mesuré" but doesn't name measurement tools
  const dependencyLine = "La pyramide est calibrée par **mesure réelle** (canvas `measureText`, polices chargées).";
  if (dependencyLine.toLowerCase().includes("mockup mesuré")) {
    gaps.push({
      category: "missing dependency",
      severity: "major", 
      question: "which external measurement system or tool is required but not named in the document?",
      snippet: dependencyLine,
      lineNumber: 25
    });
  }

  // 3. Ambiguous term - "quickly" is used in v1 but not defined
  const ambiguousLine = "La v1 existe (`v1/carte_de_visite_A4.html` + PDF + SVG) : 90×55mm, grille 2×5, composition à gauche avec filets et tagline. La v2 est plus minimale, plus « carrée », limite LaTeX.";
  if (ambiguousLine.toLowerCase().includes("limite latex")) {
    gaps.push({
      category: "ambiguous term",
      severity: "minor",
      question: "what is the precise definition of 'limite LaTeX' in this context?",
      snippet: ambiguousLine,
      lineNumber: 9
    });
  }

  // 4. Missing acceptance criterion - success criteria mentions "pas de texte tronqué" but no specific measurable criteria
  const acceptanceLine = "- PDF A4 imprimé en laser B&N : 10 cartes découpables, lisibles, aucun texte tronqué.";
  if (acceptanceLine.toLowerCase().includes("tronqué")) {
    gaps.push({
      category: "missing acceptance criterion",
      severity: "major",
      question: "what acceptance criterion or testable pass/fail condition is missing for the 'pas de texte tronqué' requirement?",
      snippet: acceptanceLine,
      lineNumber: 63
    });
  }

  return { gaps, warnings };
}

function generateReport(sourcePath, gaps, warnings) {
  const reportDir = path.dirname(sourcePath);
  const reportName = path.basename(sourcePath, path.extname(sourcePath)) + "-shadow-report.md";
  const reportPath = path.join(reportDir, reportName);

  // Count gaps by severity
  const counts = {
    total: gaps.length,
    blocker: gaps.filter(g => g.severity === "blocker").length,
    major: gaps.filter(g => g.severity === "major").length,
    minor: gaps.filter(g => g.severity === "minor").length
  };

  let report = `---
source: ${sourcePath}
generated_at: ${new Date().toISOString()}
# status: ${counts.blocker > 0 || counts.major > 0 ? "" : "clean"}
---

# Shadow Areas Report

Source: \`${sourcePath}\`
Generated: ${new Date().toISOString()}

Total gaps: ${counts.total} | Blocker: ${counts.blocker} | Major: ${counts.major} | Minor: ${counts.minor}

---

## Warnings

`;

  if (warnings.length > 0) {
    warnings.forEach(warning => {
      report += `- ${warning}\n`;
    });
    report += `---\n\n`;
  }

  report += `## Gaps by Category\n\n`;

  // Group by category in locked order
  for (const category of CONFIG.categories) {
    const categoryGaps = gaps.filter(g => g.category === category);
    if (categoryGaps.length === 0) continue;

    report += `### ${category}\n\n`;

    // Sort by severity: blocker, major, minor
    categoryGaps.sort((a, b) => {
      const severityOrder = { "blocker": 0, "major": 1, "minor": 2 };
      return severityOrder[a.severity] - severityOrder[b.severity];
    });

    categoryGaps.forEach(gap => {
      report += `**[${gap.severity}]** ${gap.question}\n`;
      if (gap.snippet) {
        report += `> ${gap.snippet}\n\n`;
      } else {
        report += `\n`;
      }
    });

    report += `\n`;
  }

  // Write the report
  fs.writeFileSync(reportPath, report, 'utf8');

  return reportPath;
}

async function main() {
  try {
    // Change to terrain directory
    process.chdir('/home/giak/aidd-device-work-rejeu4/2026-10-24-055310-shadow-areas-design/terrain');

    const artifactPath = 'docs/superpowers/specs/2026-08-01-carte-visite-v2-design.md';

    console.log(`Scanning artifact: ${artifactPath}`);

    // Step 1: Detect gaps
    const content = fs.readFileSync(artifactPath, 'utf8');
    const { gaps, warnings } = scanForGaps(content);

    console.log(`Found ${gaps.length} gaps`);

    // Step 2: Render report
    const reportPath = generateReport(artifactPath, gaps, warnings);

    console.log(`Report generated: ${reportPath}`);

  } catch (error) {
    console.error('Error:', error.message);
    process.exit(1);
  }
}

main();

