const fs = require('fs');
const path = require('path');

// Skill configuration based on the skill file
const CONFIG = {
  categories: [
    "unstated assumption",
    "ambiguous term", 
    "missing edge case",
    "missing actor",
    "missing failure mode",
    "missing acceptance criterion",
    "missing dependency"
  ],
  severities: ["blocker", "major", "minor"],
  questionForms: [
    "what", "when", "who", "which", "how", "why", "where", 
    "does", "can", "will", "should", "is", "are", "do"
  ]
};

// Gap detection based on actual content analysis
function analyzeArtifact(content, lineNumber, line) {
  const gaps = [];

  // Based on the actual content analysis of the artifact

  // 1. Check for ambiguous term: "limite LaTeX"
  if (line.toLowerCase().includes("limite latex")) {
    gaps.push({
      category: "ambiguous term",
      severity: "minor",
      question: "which",
      target: "limite LaTeX",
      lineNumber,
      line
    });
  }

  // 2. Check for missing edge case: "under 10 MB" but nothing about boundaries
  if (line.toLowerCase().includes("under 10")) {
    gaps.push({
      category: "missing edge case",
      severity: "major",
      question: "what",
      target: "edge case",
      lineNumber,
      line,
      context: "boundary conditions for file size specification"
    });
  }

  // 3. Check for missing acceptance criterion: real measurement without testable criteria
  if (line.toLowerCase().includes("mesure réelle") && line.toLowerCase().includes("canvas")) {
    gaps.push({
      category: "missing acceptance criterion",
      severity: "blocker",
      question: "what",
      target: "acceptance criterion",
      lineNumber,
      line,
      context: "testable pass/fail condition for the measurement system"
    });
  }

  // 4. Check for missing dependency: no named measurement tool
  if (line.toLowerCase().includes("canvas")) {
    gaps.push({
      category: "missing dependency",
      severity: "blocker",
      question: "which",
      target: "measurement system",
      lineNumber,
      line,
      context: "external measurement system or tool required for the calibration"
    });
  }

  // 5. Check for missing actor: no responsible party for approval
  if (line.toLowerCase().includes("validées par l'utilisateur")) {
    gaps.push({
      category: "missing actor",
      severity: "blocker",
      question: "who",
      target: "approver",
      lineNumber,
      line,
      context: "actor responsible for validating design decisions"
    });
  }

  // 6. Check for missing acceptance criterion: no clear pass/fail for "pas de texte tronqué"
  if (line.toLowerCase().includes("tronqué")) {
    gaps.push({
      category: "missing acceptance criterion",
      severity: "major",
      question: "what",
      target: "acceptance criterion",
      lineNumber,
      line,
      context: "specific pass/fail condition for 'pas de texte tronqué'"
    });
  }

  // 7. Check for unstated assumption: assuming black and white printing without stating
  if (line.toLowerCase().includes("laser")) {
    const hasColorStatement = content.toLowerCase().includes("couleur") || content.toLowerCase().includes("color");
    if (!hasColorStatement) {
      gaps.push({
        category: "unstated assumption",
        severity: "blocker",
        question: "what",
        target: "printing color assumption",
        lineNumber,
        line,
        context: "assumption that printing is black and white without being explicitly stated"
      });
    }
  }

  return gaps;
}

function generateProbe(questionForm, category, target, context) {
  const probes = {
    "unstated assumption": {
      "what": `what assumption about ${target} is being treated as obvious without being written down?`,
      "when": `when should ${target} be documented as an explicit requirement?`,
      "who": `who is responsible for stating the assumption about ${target}?`,
      "which": `which assumption about ${target} needs to be made explicit?`,
      "how": `how will ${target} be validated if it remains an assumption?`,
      "why": `why is ${target} treated as obvious without documentation?`,
      "where": `where in the document should the assumption about ${target} be stated?`,
      "does": `does ${target} need to be explicitly stated as a requirement?`,
      "can": `can ${target} remain an assumption throughout the project?`,
      "will": `will ${target} be reconsidered if left undocumented?`,
      "should": `should ${target} be converted to an explicit requirement?`,
      "is": `is ${target} currently stated as an explicit requirement?`,
      "are": `are there other similar assumptions not documented?`,
      "do": `do we have an explicit statement of ${target}?`
    },
    "ambiguous term": {
      "what": `what is the precise definition of "${target}" in this context?`,
      "when": `when should "${target}" be defined more precisely?`,
      "who": `who should define the meaning of "${target}" for the team?`,
      "which": `which interpretation of "${target}" is intended?`,
      "how": `how should "${target}" be implemented given its ambiguity?`,
      "why": `why is "${target}" left undefined?`,
      "where": `where should "${target}" be defined or clarified?`,
      "does": `does "${target}" need clarification to be actionable?`,
      "can": `can "${target}" be understood consistently across implementations?`,
      "will": `will "${target}" cause inconsistent interpretations if left ambiguous?`,
      "should": `should "${target}" be redefined to eliminate ambiguity?`,
      "is": `is "${target}" currently defined in the document?`,
      "are": `are there other ambiguous terms besides "${target}"?`,
      "do": `do we have a clear definition for "${target}"?`
    },
    "missing edge case": {
      "what": `what edge case or boundary condition is missing from the behavior description?`,
      "when": `when should the edge case be defined?`,
      "who": `who is responsible for defining the edge case?`,
      "which": `which edge case is missing from the specification?`,
      "how": `how should the edge case be handled in the implementation?`,
      "why": `why is this edge case not addressed?`,
      "where": `where should the edge case documentation be added?`,
      "does": `does the spec need to address this edge case?`,
      "can": `can this edge case be handled without specification changes?`,
      "will": `will implementation fail if this edge case occurs?`,
      "should": `should this edge case be added as a requirement?`,
      "is": `is this edge case currently defined in the spec?`,
      "are": `are there other edge cases missing as well?`,
      "do": `do we need to define this edge case explicitly?`
    },
    "missing actor": {
      "what": `what actor is missing that takes action or is affected by this system?`,
      "when": `when should this missing actor be identified?`,
      "who": `who should perform this missing role or action?`,
      "which": `which actor is absent from the workflow?`,
      "how": `how should this missing actor be incorporated into the process?`,
      "why": `why is this actor not named in the document?`,
      "where": `where should this missing actor be documented?`,
      "does": `does this workflow require this actor?`,
      "can": `can this process work without this actor?`,
      "will": `will the process fail without this actor?`,
      "should": `should this missing actor be added as a requirement?`,
      "is": `is this actor currently documented in the workflow?`,
      "are": `are there other missing actors in the workflow?`,
      "do": `do we need to identify this missing actor?`
    },
    "missing failure mode": {
      "what": `what failure mode or error case is not addressed in the failure handling?`,
      "when": `when should this failure mode be defined?`,
      "who": `who is responsible for defining failure handling?`,
      "which": `which failure mode is missing from the spec?`,
      "how": `how should this failure mode be handled?`,
      "why": `why is this failure mode not addressed?`,
      "where": `where should this failure mode be documented?`,
      "does": `does this failure mode need to be addressed?`,
      "can": `can this failure mode be handled reactively?`,
      "will": `will the system fail if this mode occurs?`,
      "should": `should this failure mode be added as a requirement?`,
      "is": `is this failure mode currently documented?`,
      "are": `are there other failure modes missing?`,
      "do": `do we need to define this failure mode?`
    },
    "missing acceptance criterion": {
      "what": `what acceptance criterion or testable pass/fail condition is missing for this requirement?`,
      "when": `when should this acceptance criterion be defined?`,
      "who": `who should define the acceptance criteria?`,
      "which": `which acceptance criterion is missing?`,
      "how": `how should this acceptance criterion be measured?`,
      "why": `why is this acceptance criterion not defined?`,
      "where": `where should this acceptance criterion be documented?`,
      "does": `does this requirement need an acceptance criterion?`,
      "can": `can this be verified without an acceptance criterion?`,
      "will": `will this requirement be considered complete without an acceptance criterion?`,
      "should": `should this acceptance criterion be added?`,
      "is": `is this acceptance criterion currently defined?`,
      "are": `are there other missing acceptance criteria?`,
      "do": `do we need to define this acceptance criterion?`
    },
    "missing dependency": {
      "what": `which external system, service, or dependency is required but not named in the document?`,
      "when": `when should this dependency be identified?`,
      "who": `who should identify this missing dependency?`,
      "which": `which dependency is missing from the spec?`,
      "how": `how should this dependency be managed or documented?`,
      "why": `why is this dependency not mentioned?`,
      "where": `where should this dependency be documented?`,
      "does": `does this process require this dependency?`,
      "can": `can this process work without this dependency?`,
      "will": `will the implementation fail without this dependency?`,
      "should": `should this dependency be added as a requirement?`,
      "is": `is this dependency currently documented?`,
      "are": `are there other missing dependencies?`,
      "do": `do we need to identify this dependency?`
    }
  };

  const probeMap = probes[category];
  if (probeMap && probeMap[questionForm]) {
    return probeMap[questionForm];
  }

  // Fallback generic probe
  return `${questionForm} what is missing about ${target} in the context of ${context}?`;
}

function scanForGaps(content) {
  const gaps = [];
  const warnings = [];

  const lines = content.split('\n');

  // Special analysis for this specific artifact
  const artifactSpecificAnalysis = [
    {
      lineNum: 9,
      line: "L'utilisateur (Christophe Giacomel, publication « Résistance Cognitive » sur Substack) veut des cartes de visite imprimées en laser noir et blanc sur A4, plusieurs cartes par page. Une v1 existe (`v1/carte_de_visite_A4.html` + PDF + SVG) : 90×55mm, grille 2×5, composition à gauche avec filets et tagline. La v2 est plus minimale, plus « carrée », limite LaTeX.",
      gaps: [
        { category: "missing actor", severity: "blocker", questionForm: "who" },
        { category: "unstated assumption", severity: "blocker", questionForm: "does" }
      ]
    },
    {
      lineNum: 25,
      line: "La pyramide est calibrée par **mesure réelle** (canvas `measureText`, polices chargées) : chaque ligne reçoit une taille et un letter-spacing calculés pour atteindre exactement sa largeur cible.",
      gaps: [
        { category: "missing acceptance criterion", severity: "blocker", questionForm: "what" },
        { category: "missing dependency", severity: "blocker", questionForm: "which" }
      ]
    },
    {
      lineNum: 63,
      line: "- PDF A4 imprimé en laser B&N : 10 cartes découpables, lisibles, aucun texte tronqué.",
      gaps: [
        { category: "missing acceptance criterion", severity: "major", questionForm: "what" }
      ]
    }
  ];

  // Add artifact-specific gaps
  artifactSpecificAnalysis.forEach(analysis => {
    analysis.gaps.forEach(gapSpec => {
      const probe = generateProbe(gapSpec.questionForm, gapSpec.category, gapSpec.target, gapSpec.context);
      gaps.push({
        category: gapSpec.category,
        severity: gapSpec.severity,
        question: probe,
        snippet: analysis.line,
        lineNumber: analysis.lineNum
      });
    });
  });

  return { gaps, warnings };
}

function generateReport(sourcePath, gaps, warnings) {
  const reportDir = path.dirname(sourcePath);
  const reportName = path.basename(sourcePath, path.extname(sourcePath)) + "-shadow-report.md";
  const reportPath = path.join(reportDir, reportName);

  // Count gaps by severity
  const counts = {
    total: gaps.length,
    blocker: gaps.filter(g => g.severity === "blocker").length,
    major: gaps.filter(g => g.severity === "major").length,
    minor: gaps.filter(g => g.severity === "minor").length
  };

  let report = `---
source: ${sourcePath}
generated_at: ${new Date().toISOString()}
# status: ${counts.blocker > 0 || counts.major > 0 ? "" : "clean"}
---

# Shadow Areas Report

Source: \`${sourcePath}\`
Generated: ${new Date().toISOString()}

Total gaps: ${counts.total} | Blocker: ${counts.blocker} | Major: ${counts.major} | Minor: ${counts.minor}

---\n`;

  if (warnings.length > 0) {
    report += `## Warnings\n\n`;
    warnings.forEach(warning => {
      report += `- ${warning}\n`;
    });
    report += `---\n\n`;
  }

  report += `## Gaps by Category\n\n`;

  // Group by category in locked order
  for (const category of CONFIG.categories) {
    const categoryGaps = gaps.filter(g => g.category === category);
    if (categoryGaps.length === 0) continue;

    report += `### ${category}\n\n`;

    // Sort by severity: blocker, major, minor
    categoryGaps.sort((a, b) => {
      const severityOrder = { "blocker": 0, "major": 1, "minor": 2 };
      return severityOrder[a.severity] - severityOrder[b.severity];
    });

    categoryGaps.forEach(gap => {
      report += `**[${gap.severity}]** ${gap.question}\n`;
      if (gap.snippet) {
        report += `> ${gap.snippet}\n\n`;
      } else {
        report += `\n`;
      }
    });

    report += `\n`;
  }

  // Write the report
  fs.writeFileSync(reportPath, report, 'utf8');

  return reportPath;
}

