function assessSeverity(line, category) {
  // Simple heuristic based on the skill spec rules
  const blockerKeywords = ["missing", "not stated", "not named", "requirement", "actor", "acceptance", "external"];
  const majorKeywords = ["ambiguous", "unclear", "failure", "edge", "error", "boundary", "exceptional"];

  const lowerText = line.toLowerCase();
  const lowerCat = category.toLowerCase();

  if (blockerKeywords.some(kw => lowerText.includes(kw) || lowerCat.includes(kw))) {
    return "blocker";
  } else if (majorKeywords.some(kw => lowerText.includes(kw) || lowerCat.includes(kw))) {
    return "major";
  }
  return "minor";
}

function scanForGaps(content) {
  const gaps = [];
  const warnings = [];

