    warnings.push("Empty source: nothing to scan");
    return { gaps, warnings };
  }

  const lines = content.split('\n');

  // Scan for gaps in each category (as per spec)
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];

    for (const category of LOCKED_SETS.categories) {
      const def = CATEGORY_DEFS[category];
      if (!def) continue;

      // Simple keyword-based detection for demonstration
      const keywords = Object.values(def.examples).flat();
      const hasRelevantKeywords = keywords.some(keyword => 
        line.toLowerCase().includes(keyword.toLowerCase())
      );

      if (hasRelevantKeywords) {
        const severity = assessSeverity(line, category);
        const probe = def.getProbe("this");

        // Validate probe format (as per spec)
        if (!probe.endsWith('?')) {
          warnings.push(`Probe for category '${category}' does not end with '?'`);
        }

        gaps.push({
          category,
          severity,
          question: probe,
          snippet: line,
          lineNumber: i + 1
        });
      }
    }
  }

  // Additional gap detection based on artifact analysis
