    { num: 63, content: "- PDF A4 imprimé en laser B&N : 10 cartes découpables, lisibles, aucun texte tronqué.", category: "missing acceptance criterion" }
  ];

  // Add specific gaps based on artifact analysis
  for (const artifactLine of artifactLines) {
    // Check if we already have a gap for this line
    const existingGap = gaps.find(gap => gap.lineNumber === artifactLine.num && gap.category === artifactLine.category);

    if (!existingGap) {
      // Generate specific probe for this artifact
      const category = artifactLine.category;
      const def = CATEGORY_DEFS[category];
      const probe = def.getProbe("this");

