  // Gap 7: Missing acceptance criterion - text truncation
  const truncationLine = "- PDF A4 imprimé en laser B&N : 10 cartes découpables, lisibles, aucun texte tronqué.";
  gaps.push({
    category: "missing acceptance criterion",
    severity: "major",
    question: "what acceptance criterion or testable pass/fail condition is missing for the 'pas de texte tronqué' requirement?",
    snippet: truncationLine,
    lineNumber: 63
  });

  return { gaps, warnings };
}

function renderReport(gaps, warnings, sourcePath) {
  // Generate report path (as per skill spec)
  const reportDir = path.dirname(sourcePath);
  const reportName = path.basename(sourcePath, path.extname(sourcePath)) + "-shadow-report.md";
  const reportPath = path.join(reportDir, reportName);

  // Count gaps by severity (as per skill spec)
  const counts = {
    total: gaps.length,
    blocker: gaps.filter(g => g.severity === "blocker").length,
    major: gaps.filter(g => g.severity === "major").length,
    minor: gaps.filter(g => g.severity === "minor").length
  };

  let report = `---
source: ${sourcePath}
generated_at: ${new Date().toISOString()}
# status: ${counts.blocker > 0 || counts.major > 0 ? "" : "clean"}
---

# Shadow Areas Report

Source: \`${sourcePath}\`
Generated: ${new Date().toISOString()}

Total gaps: ${counts.total} | Blocker: ${counts.blocker} | Major: ${counts.major} | Minor: ${counts.minor}

---\n`;

  // Add warnings if present (as per skill spec)
  if (warnings.length > 0) {
    report += `## Warnings\n\n`;
    warnings.forEach(warning => {
      report += `- ${warning}\n`;
    });
    report += `---\n\n`;
  }

  report += `## Gaps by Category\n\n`;

  // Group by category in locked order (as per skill spec)
  for (const category of LOCKED_SETS.categories) {
    const categoryGaps = gaps.filter(g => g.category === category);
    if (categoryGaps.length === 0) continue;

    report += `### ${category}\n\n`;

    // Sort by severity: blocker, major, minor (as per skill spec)
    categoryGaps.sort((a, b) => {
      const severityOrder = { "blocker": 0, "major": 1, "minor": 2 };
      return severityOrder[a.severity] - severityOrder[b.severity];
    });

    categoryGaps.forEach(gap => {
      // Render each gap (as per skill spec)
      report += `**[${gap.severity}]** ${gap.question}\n`;
      if (gap.snippet) {
        report += `> ${gap.snippet}\n\n`;
      } else {
        report += `\n`;
      }
    });

    report += `\n`;
  }

  // Write report (as per skill spec)
  fs.writeFileSync(reportPath, report, 'utf8');

  return reportPath;
}

